fn damage_spell_states() -> (GameState, GameState) {
    let mut scenario = GameScenario::new_n_player(2, 7);
    scenario.at_phase(Phase::PreCombatMain);
    let bolt = scenario.add_bolt_to_hand(P0);
    let mut runner = scenario.build();
    let pre_state = runner.state().clone();

    let outcome = runner.cast(bolt).target_player(P1).resolve();
    outcome.assert_life_delta(P1, -3);

    (pre_state, runner.state().clone())
}

/// A real damage spell records the final post-replacement life delta. Replaying
/// that semantic command changes only the retained prefix's player resources.
#[test]
fn real_damage_spell_replays_recorded_final_life_delta() {
    let (pre_state, ordinary_state) = damage_spell_states();
    let commands = semantic_commands(&ordinary_state);
    let life_command = commands
        .iter()
        .find(|command| {
            matches!(
                command,
                ResolvedRulesCommand::PlayerEdit(ResolvedPlayerEditCommand {
                    player: P1,
                    edit: ResolvedPlayerEdit::Life { delta: -3 },
                    ..
                })
            )
        })
        .expect("Lightning Bolt must journal its final delivered life delta");

    let mut replay = pre_state;
    replay.resolved_rules_journal = ordinary_state.resolved_rules_journal.clone();
    apply_semantic_command(&mut replay, life_command);

    let replayed = replay
        .players
        .iter()
        .find(|player| player.id == P1)
        .unwrap();
    let ordinary = ordinary_state
        .players
        .iter()
        .find(|player| player.id == P1)
        .unwrap();
    assert_eq!(replayed.life, ordinary.life);
    assert_eq!(
        replayed.life_lost_this_turn, ordinary.life_lost_this_turn,
        "the final delta carries life-loss bookkeeping without rerunning replacement"
    );
}

/// Exact status commands are intentionally non-idempotent: replaying a recorded
/// tap twice fails its old-status precondition, and a same-id new incarnation
/// fails rather than accepting a stale reference.
#[test]
fn recorded_tap_rejects_double_apply_and_stale_incarnation() {
    let (pre_state, ordinary_state, signet) = activated_signet_states();
    let command = semantic_commands(&ordinary_state)
        .into_iter()
        .find_map(|command| match command {
            ResolvedRulesCommand::ObjectStatus(command) if command.object.object_id == signet => {
                Some(command)
            }
            _ => None,
        })
        .expect("the real Signet activation must journal its tap cost");

    let mut replay = pre_state.clone();
    engine::game::object_state::apply_resolved_object_edit(&mut replay, &command).unwrap();
    assert!(matches!(
        engine::game::object_state::apply_resolved_object_edit(&mut replay, &command),
        Err(ResolvedObjectStatusReplayInvariantError::StatusPreconditionMismatch { .. })
    ));

    let mut stale = pre_state;
    stale
        .objects
        .get_mut(&command.object.object_id)
        .unwrap()
        .bump_incarnation();
    assert!(matches!(
        engine::game::object_state::apply_resolved_object_edit(&mut stale, &command),
        Err(ResolvedObjectStatusReplayInvariantError::StaleObject { .. })
    ));
}

/// Scalar deltas compose until the resource's actual precondition rejects a
/// duplicate removal; no player snapshot is restored over an independent edit.
#[test]
fn exact_scalar_resource_removal_rejects_a_second_underflowing_apply() {
    let mut state = GameState::new_two_player(7);
    state.players[0].energy = 1;
    let command = ResolvedPlayerEditCommand {
        player: P0,
        edit: ResolvedPlayerEdit::Energy { delta: -1 },
        cause: RulesExecutionNodeRef::Proposal(
            engine::types::resolved_commands::ResolvedCommandOrdinal(0),
        ),
    };

    state.apply_resolved_player_edit(&command).unwrap();
    assert!(matches!(
        state.apply_resolved_player_edit(&command),
        Err(ResolvedPlayerEditReplayInvariantError::ResourceUnderflow)
    ));
}

/// The scalar authority edits one resource axis at a time. It records semantic
/// deltas/transitions instead of replacing a player snapshot, so unrelated
/// retained resource edits remain intact.
#[test]
fn scalar_commands_compose_across_life_energy_counters_and_speed() {
    let mut state = GameState::new_two_player(7);

    state
        .resolve_and_apply_player_edit(P0, ResolvedPlayerEdit::Life { delta: 2 })
        .unwrap();
    state
        .resolve_and_apply_player_edit(P0, ResolvedPlayerEdit::Energy { delta: 3 })
        .unwrap();
    state
        .resolve_and_apply_player_edit(
            P0,
            ResolvedPlayerEdit::Counter {
                kind: PlayerCounterKind::Experience,
                delta: 1,
            },
        )
        .unwrap();
    state
        .resolve_and_apply_player_edit(
            P0,
            ResolvedPlayerEdit::Speed {
                old: None,
                new: Some(3),
            },
        )
        .unwrap();

    let player = state.players.iter().find(|player| player.id == P0).unwrap();
    assert_eq!(player.life, 22);
    assert_eq!(player.life_gained_this_turn, 2);
    assert_eq!(player.energy, 3);
    assert_eq!(
        player.player_counter(&PlayerCounterKind::Experience),
        1,
        "the counter edit must not overwrite the preceding scalar edits"
    );
    assert_eq!(player.speed, Some(3));
    assert_eq!(
        semantic_commands(&state).len(),
        4,
        "each final scalar edit has one journal command"
    );
}

/// players, player-only attack targets, no trample, no extra-block capacity,
/// no triggered/replacement continuation, and no damage-assignment choice.
/// Those exclusions are soundness boundaries, not heuristic shortcuts.
pub fn adversarial_swarm_witness(
    state: &GameState,
    attacking_player: PlayerId,
    attacks: &[(crate::types::identifiers::ObjectId, AttackTarget)],
) -> SwarmWitnessResult {
    swarm_witness_inner(state, attacking_player, attacks, None)
}

#[cfg(feature = "test-support")]
pub fn adversarial_swarm_witness_with_counters(
    state: &GameState,
    attacking_player: PlayerId,
    attacks: &[(crate::types::identifiers::ObjectId, AttackTarget)],
    counters: &mut SwarmWitnessCounters,
) -> SwarmWitnessResult {
    swarm_witness_inner(state, attacking_player, attacks, Some(counters))
}

fn swarm_witness_inner(
    state: &GameState,
    attacking_player: PlayerId,
    attacks: &[(crate::types::identifiers::ObjectId, AttackTarget)],
    #[allow(unused_mut, unused_variables)] mut counters: Option<&mut SwarmWitnessCounters>,
) -> SwarmWitnessResult {
    if state.players.len() != 2 || state.format_config.team_based {
        return indeterminate(SwarmWitnessIndeterminate::UnsupportedTopology);
    }
    let WaitingFor::DeclareAttackers { player, .. } = &state.waiting_for else {
        return indeterminate(SwarmWitnessIndeterminate::InvalidAttack);
    };
    if *player != attacking_player || state.active_player != attacking_player || attacks.is_empty()
    {
        return indeterminate(SwarmWitnessIndeterminate::InvalidAttack);
    }

    let Some(defending_player) = attacks.first().and_then(|(_, target)| match target {
        AttackTarget::Player(player) => Some(*player),
        AttackTarget::Planeswalker(_) | AttackTarget::Battle(_) => None,
    }) else {
        return indeterminate(SwarmWitnessIndeterminate::NonPlayerTarget);
    };
    if defending_player == attacking_player
        || attacks
            .iter()
            .any(|(_, target)| *target != AttackTarget::Player(defending_player))
    {
        return indeterminate(SwarmWitnessIndeterminate::InvalidAttack);
    }

    let mut declaration = Vec::with_capacity(attacks.len());
    let mut attackers = Vec::with_capacity(attacks.len());
    for (attacker_id, _) in attacks {
        let Some(attacker) = state.objects.get(attacker_id) else {
            return indeterminate(SwarmWitnessIndeterminate::InvalidAttack);
        };
        if attacker.has_keyword(&Keyword::Trample)
            || attacker.has_keyword(&Keyword::TrampleOverPlaneswalkers)
        {
            return indeterminate(SwarmWitnessIndeterminate::DamageChoice);
        }
        let attacker_ref = ObjectIncarnationRef::from_object(attacker);
        declaration.push((attacker_ref, defending_player));
        attackers.push(attacker_ref);
    }
    attackers.sort_unstable();
    attackers.dedup();
    if attackers.len() != attacks.len() {
        return indeterminate(SwarmWitnessIndeterminate::InvalidAttack);
    }

    #[cfg(feature = "test-support")]
    if let Some(counters) = &mut counters {
        counters.root_clone_applies += 1;
    }
    let mut after_attack = state.clone();
    let attack_events = match apply_as_current_for_simulation(
        &mut after_attack,
        GameAction::DeclareAttackers {
            attacks: attacks.to_vec(),
            bands: vec![],
        },
    ) {
        Ok(result) => result.events,
        // This action was formed from the caller's exact declaration; an engine
        // rejection cannot authorize a swarm claim.
        Err(_) => return indeterminate(SwarmWitnessIndeterminate::InvalidAttack),
    };
    if has_unmodeled_combat_event(&attack_events) || !after_attack.stack.is_empty() {
        return indeterminate(SwarmWitnessIndeterminate::TriggerOrReplacement);
    }
    // CR 510.1 + CR 614.1a: combat damage is assigned after blockers, and an
    // applicable replacement is a reducer boundary. Decline early rather than
    // driving priority past a damage replacement the witness cannot choose.
    if has_applicable_combat_damage_replacement(&after_attack) {
        return indeterminate(SwarmWitnessIndeterminate::TriggerOrReplacement);
    }
    if let Err(reason) = advance_to_blocker_declaration(&mut after_attack, defending_player) {
        return indeterminate(reason);
    }
    // CR 509.1a: The reducer may have submitted the unique empty declaration
    // while advancing from the attackers step. That is a complete defender
    // choice, not an unsupported prompt.
    let blockers_auto_declared = after_attack
        .combat
        .as_ref()
        .is_some_and(|combat| combat.blockers_declared_by.contains(&defending_player))
        || (after_attack.phase == Phase::DeclareBlockers
            && matches!(after_attack.waiting_for, WaitingFor::Priority { .. })
            && combat::get_valid_block_targets_for_player(&after_attack, defending_player)
                .is_empty());

    let (valid_blockers, valid_targets) = match &after_attack.waiting_for {
        WaitingFor::DeclareBlockers {
            player,
            valid_blocker_ids,
            valid_block_targets,
            ..
        } if *player == defending_player => {
            (valid_blocker_ids.clone(), valid_block_targets.clone())
        }
        _ if blockers_auto_declared => (Vec::new(), Default::default()),
        _ => return indeterminate(SwarmWitnessIndeterminate::CostOrPrompt),
    };
    if valid_blockers.iter().any(|blocker_id| {
        after_attack.objects.get(blocker_id).is_some_and(|blocker| {
            active_static_definitions(&after_attack, blocker)
                .any(|static_def| matches!(static_def.mode, StaticMode::ExtraBlockers { .. }))
        })
    }) {
        return indeterminate(SwarmWitnessIndeterminate::MultiBlockChoice);
    }
    let blocker_candidates = valid_blockers
        .iter()
        .filter_map(|blocker_id| after_attack.objects.get(blocker_id))
        .map(ObjectIncarnationRef::from_object)
        .collect();

    if checked_declaration_product(&valid_blockers, &valid_targets).is_none() {
        return indeterminate(SwarmWitnessIndeterminate::DeclarationCap);
    }
    let defending_life_before = player_life(&after_attack, defending_player);

    let mut worst: Option<(u32, Vec<(ObjectIncarnationRef, ObjectIncarnationRef)>)> = None;
    let mut failure = None;
    let mut scratch = Vec::new();
    let _ = stream_declarations(
        &valid_blockers,
        &valid_targets,
        0,
        &mut scratch,
        &mut |declaration| {
            #[cfg(feature = "test-support")]
            if let Some(counters) = &mut counters {
                counters.raw_leaves += 1;
            }
            if combat::validate_blockers_for_player(&after_attack, defending_player, declaration)
                .is_err()
            {
                return ControlFlow::Continue(());
            }
            #[cfg(feature = "test-support")]
            if let Some(counters) = &mut counters {
                counters.legal_leaves += 1;
                counters.candidate_clone_applies += 1;
            }
            let mut branch = after_attack.clone();
            if !blockers_auto_declared {
                let result = match apply_as_current_for_simulation(
                    &mut branch,
                    GameAction::DeclareBlockers {
                        assignments: declaration.to_vec(),
                    },
                ) {
                    Ok(result) => result,
                    Err(_) => {
                        failure = Some(SwarmWitnessIndeterminate::InvalidAttack);
                        return ControlFlow::Break(());
                    }
                };
                if has_unmodeled_combat_event(&result.events) || !branch.stack.is_empty() {
                    failure = Some(SwarmWitnessIndeterminate::TriggerOrReplacement);
                    return ControlFlow::Break(());
                }

        GameEvent::DamageDealt {
            target: TargetRef::Object(id),
            ..
        } => Some(*id),
        _ => None,
    }
}

/// Extract the relevant player from a trigger event.
pub(crate) fn extract_player_from_event(
    event: &crate::types::events::GameEvent,
    state: &GameState,
) -> Option<PlayerId> {
    use crate::types::events::GameEvent;
    match event {
        GameEvent::LifeChanged { player_id, .. } => Some(*player_id),
        // CR 106.4 + CR 605.1b: `ManaAdded` carries the player whose pool gained
        // the mana — equivalently, the player who tapped the source for mana.
        // For TapsForMana triggers (Fertile Ground / Wild Growth / Utopia Sprawl
        // and the wider "its controller adds…" Aura class), this is the
        // enchanted land's controller, which `PlayerFilter::TriggeringPlayer`
        // rebinds as the resolving ability's controller so the bonus mana
        // routes to the tapper even when the Aura is opponent-controlled.
        GameEvent::ManaAdded { player_id, .. } => Some(*player_id),
        // CR 106.12a + CR 605.1b: `TappedForMana` carries the player who tapped
        // the source for mana — the triggering player for `TapsForMana`.
        GameEvent::TappedForMana { player_id, .. } => Some(*player_id),
        GameEvent::CardsDrawn { player_id, .. } => Some(*player_id),
        GameEvent::CardDrawn { player_id, .. } => Some(*player_id),
        GameEvent::Discarded { player_id, .. } => Some(*player_id),
        GameEvent::LandPlayed { player_id, .. } => Some(*player_id),
        GameEvent::SpellCast { controller, .. } => Some(*controller),
        // CR 602.2a: "Its controller is the player who activated the ability."
        // For "Whenever a player activates an ability, … deals 1 damage to that
        // player" triggers (Burning-Tree Shaman, Flamescroll Celebrant),
        // `TriggeringPlayer` / "that player" binds to the activating player
        // carried on the event.
        GameEvent::AbilityActivated { player_id, .. } => Some(*player_id),
        GameEvent::PermanentSacrificed { player_id, .. } => Some(*player_id),
        GameEvent::Unattached {
            old_target: TargetRef::Player(player_id),
            ..
        } => Some(*player_id),
        GameEvent::Cycled { player_id, .. } => Some(*player_id),
        GameEvent::PlayerPerformedAction { player_id, .. } => Some(*player_id),
        GameEvent::CrimeCommitted { player_id, .. } => Some(*player_id),
        GameEvent::PlayerEliminated { player_id, .. } => Some(*player_id),
        // CR 506.2 + CR 508.1: The attacking player is the common controller of the
        // declared attackers in this batch. All attackers in one AttackersDeclared
        // batch share the active player as their controller.
        GameEvent::AttackersDeclared { attacker_ids, .. } => attacker_ids
            .iter()
            .find_map(|id| state.objects.get(id).map(|obj| obj.controller)),
        GameEvent::BecomesTarget {
            target,
            source_controller,
            ..
        } => match target {
            TargetRef::Player(player_id) => Some(*player_id),
            TargetRef::Object(_) => Some(*source_controller),
        },
        // CR 603.7c: "that player" for DamageDone triggers refers to the damaged player.
